import copy
import json
import math
from solution import solve


def close(actual, expected):
    if isinstance(expected, bool) or expected is None:
        return actual is expected
    if isinstance(expected, (int, float)):
        return isinstance(actual, (int, float)) and not isinstance(actual, bool) and math.isfinite(actual) and math.isclose(actual, expected, abs_tol=1e-8, rel_tol=1e-9)
    if isinstance(expected, list):
        return isinstance(actual, list) and len(actual) == len(expected) and all(close(a, e) for a, e in zip(actual, expected))
    if isinstance(expected, dict):
        return isinstance(actual, dict) and actual.keys() == expected.keys() and all(close(actual[k], v) for k, v in expected.items())
    return actual == expected


CASES = json.loads("[{\"name\":\"pure_resistor\",\"input\":{\"resistance_ohm\":10,\"inductance_h\":0,\"capacitance_f\":null,\"frequency_hz\":50,\"voltage_rms_v\":20},\"expected\":{\"impedance_ohm\":[10,0],\"current_rms_a\":2,\"current_phase_deg\":0}},{\"name\":\"pure_inductor\",\"input\":{\"resistance_ohm\":0,\"inductance_h\":1,\"capacitance_f\":null,\"frequency_hz\":0.15915494309189535,\"voltage_rms_v\":2},\"expected\":{\"impedance_ohm\":[0,1],\"current_rms_a\":2,\"current_phase_deg\":-90}}]")
for case in CASES:
    value = copy.deepcopy(case["input"])
    assert close(solve(value), case["expected"]), case["name"]
    assert value == case["input"], "Do not mutate the input"
