def solve(payload):
    import math
    r, l, c, f, voltage = [payload[k] for k in ("resistance_ohm", "inductance_h", "capacitance_f", "frequency_hz", "voltage_rms_v")]
    if r < 0 or l < 0 or (c is not None and c <= 0) or f <= 0 or voltage < 0:
        return {"error": "invalid_component"}
    omega = 2*math.pi*f
    x = omega*l-(1/(omega*c) if c is not None else 0)
    magnitude = math.hypot(r, x)
    if magnitude == 0:
        return {"error": "zero_impedance"}
    return {"impedance_ohm": [r, x], "current_rms_a": voltage/magnitude, "current_phase_deg": -math.degrees(math.atan2(x, r))}

